SET standard_conforming_strings = on;
SET search_path = pg_catalog, public;

CREATE TABLE "public"."push_subscriptions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."push_subscriptions_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "user_id" uuid NOT NULL,
  "endpoint" text NOT NULL,
  "endpoint_hash" text NOT NULL,
  "p256dh_key" text NOT NULL,
  "auth_key" text NOT NULL,
  "device_label" text,
  "browser_name" text,
  "platform_name" text,
  "user_agent" text,
  "permission_state" text DEFAULT 'granted'::text NOT NULL,
  "is_active" boolean DEFAULT true NOT NULL,
  "last_seen_at" timestamp with time zone DEFAULT now() NOT NULL,
  "last_success_at" timestamp with time zone,
  "last_failure_at" timestamp with time zone,
  "failure_count" integer DEFAULT 0 NOT NULL,
  "revoked_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."push_subscriptions" OWNER TO "postgres";
COMMENT ON TABLE "public"."push_subscriptions" IS 'Per-user browser and device Web Push subscriptions. Endpoint and encryption fields are sensitive.';
COMMENT ON COLUMN "public"."push_subscriptions"."endpoint" IS 'Sensitive Web Push capability endpoint. Must not be exposed to unauthorized users.';
COMMENT ON COLUMN "public"."push_subscriptions"."endpoint_hash" IS 'Deterministic endpoint hash used for duplicate prevention without routine endpoint disclosure.';
COMMENT ON COLUMN "public"."push_subscriptions"."p256dh_key" IS 'Browser-provided Web Push encryption public key.';
COMMENT ON COLUMN "public"."push_subscriptions"."auth_key" IS 'Browser-provided Web Push authentication secret.';
COMMENT ON COLUMN "public"."push_subscriptions"."device_label" IS 'User-friendly device name used in notification settings.';
COMMENT ON COLUMN "public"."push_subscriptions"."failure_count" IS 'Consecutive or accumulated delivery failures used for subscription health management.';
